package org.apache.commons.cli;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;

import java.lang.reflect.Field;
import java.util.Collection;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class OptionsTest {

    private Options options;

    @BeforeEach
    void setUp() {
        options = new Options();
    }

    @Test
    void testAddRequiredOptionWithShortAndLongOpt() throws Exception {
        // act
        Options returned = options.addRequiredOption("a", "alpha", true, "description a");

        // same instance returned
        assertSame(options, returned);

        // reflectively access private maps and lists
        Field shortOptsField = Options.class.getDeclaredField("shortOpts");
        Field longOptsField = Options.class.getDeclaredField("longOpts");
        Field requiredOptsField = Options.class.getDeclaredField("requiredOpts");
        shortOptsField.setAccessible(true);
        longOptsField.setAccessible(true);
        requiredOptsField.setAccessible(true);

        Map<?, ?> shortOpts = (Map<?, ?>) shortOptsField.get(options);
        Map<?, ?> longOpts = (Map<?, ?>) longOptsField.get(options);
        List<?> requiredOpts = (List<?>) requiredOptsField.get(options);

        // ensure maps/lists updated
        assertEquals(1, shortOpts.size(), "shortOpts should contain one entry");
        assertEquals(1, longOpts.size(), "longOpts should contain one entry");
        assertEquals(1, requiredOpts.size(), "requiredOpts should contain one entry");

        // verify long option key is present and maps to the same Option instance stored in shortOpts values
        Object longOptValue = longOpts.get("alpha");
        assertNotNull(longOptValue, "longOpts should contain key 'alpha'");

        // get the key stored in shortOpts (the Option key)
        String shortKey = (String) shortOpts.keySet().iterator().next();
        Object shortOptValue = shortOpts.values().iterator().next();
        assertSame(longOptValue, shortOptValue, "shortOpts and longOpts should reference the same Option instance");

        // requiredOpts should contain the same key as the shortOpts map key
        assertEquals(shortKey, requiredOpts.get(0), "requiredOpts should contain the option key stored in shortOpts");

        // verify the Option instance has its 'required' field set to true
        Field requiredField = longOptValue.getClass().getDeclaredField("required");
        requiredField.setAccessible(true);
        boolean requiredFlag = (boolean) requiredField.get(longOptValue);
        assertTrue(requiredFlag, "Option.required should be true");
    }

    @Test
    void testAddRequiredOptionWithoutLongOpt() throws Exception {
        // act
        options.addRequiredOption("b", null, false, "description b");

        // reflectively access private maps and lists
        Field shortOptsField = Options.class.getDeclaredField("shortOpts");
        Field longOptsField = Options.class.getDeclaredField("longOpts");
        Field requiredOptsField = Options.class.getDeclaredField("requiredOpts");
        shortOptsField.setAccessible(true);
        longOptsField.setAccessible(true);
        requiredOptsField.setAccessible(true);

        Map<?, ?> shortOpts = (Map<?, ?>) shortOptsField.get(options);
        Map<?, ?> longOpts = (Map<?, ?>) longOptsField.get(options);
        List<?> requiredOpts = (List<?>) requiredOptsField.get(options);

        // shortOpts should contain an entry for 'b'
        assertEquals(1, shortOpts.size(), "shortOpts should contain one entry");
        String shortKey = (String) shortOpts.keySet().iterator().next();
        assertEquals("b", shortKey, "shortOpts key should be 'b'");

        // longOpts should not contain an entry for null or 'b'
        assertFalse(longOpts.containsKey("b"), "longOpts should not contain key 'b'");
        assertFalse(longOpts.containsKey(null), "longOpts should not contain key null");

        // requiredOpts should contain the 'b' key
        assertEquals(1, requiredOpts.size(), "requiredOpts should contain one entry");
        assertEquals("b", requiredOpts.get(0), "requiredOpts should contain 'b'");

        // verify Option.required flag is true
        Object optionInstance = shortOpts.values().iterator().next();
        Field requiredField = optionInstance.getClass().getDeclaredField("required");
        requiredField.setAccessible(true);
        assertTrue((boolean) requiredField.get(optionInstance), "Option.required should be true");
    }

    @Test
    void testAddRequiredOptionDuplicateOrdering() throws Exception {
        // add two required options in order x, y
        options.addRequiredOption("x", "ex", false, "first");
        options.addRequiredOption("y", "why", false, "second");

        // reflectively access requiredOpts
        Field requiredOptsField = Options.class.getDeclaredField("requiredOpts");
        requiredOptsField.setAccessible(true);
        List<?> requiredOpts = (List<?>) requiredOptsField.get(options);

        // expect order [x, y]
        assertEquals(2, requiredOpts.size(), "requiredOpts should contain two entries");
        assertEquals("x", requiredOpts.get(0), "first required should be 'x'");
        assertEquals("y", requiredOpts.get(1), "second required should be 'y'");

        // add x again -> should move x to the end (remove previous then add)
        options.addRequiredOption("x", "ex", false, "first-again");

        // re-read requiredOpts
        List<?> requiredOptsAfter = (List<?>) requiredOptsField.get(options);
        assertEquals(2, requiredOptsAfter.size(), "requiredOpts should still contain two entries");
        // expected order now [y, x]
        assertEquals("y", requiredOptsAfter.get(0), "after re-adding 'x', first should be 'y'");
        assertEquals("x", requiredOptsAfter.get(1), "after re-adding 'x', second should be 'x'");
    }
}

